(4342478, 625514, 30982, '<td valign="top">He''s adorable!  He photographs well, too.</td>', 'He''s adorable!  He photographs well, too.', '2007-12-29 04:48:49.000000', NULL, 1),
(4342483, 625656, 70689, '<td valign="top">I think this pic has several problems. Let''s start with the subject of a swear box. I have no idea what it is, and it is not apparent from the pic either. You miss me there, and if you miss too many voters, it will affect you score. Furthermore, your background has distracting patterns as well as disturbing wrinkels. I am also not too found of the harsh (though not blown) highlights in your pic or the central composition.</td>', 'I think this pic has several problems. Let''s start with the subject of a swear box. I have no idea what it is, and it is not apparent from the pic either. You miss me there, and if you miss too many voters, it will affect you score. Furthermore, your background has distracting patterns as well as disturbing wrinkels. I am also not too found of the harsh (though not blown) highlights in your pic or the central composition.', '2007-12-29 04:51:49.000000', NULL, 1),
(4342493, 625506, 30982, '<td valign="top">Heh!  They are very useful when they''re right, though.</td>', 'Heh!  They are very useful when they''re right, though.', '2007-12-29 05:08:30.000000', NULL, 1),
(4342495, 626107, 30982, '<td valign="top">LOL!  Can''t say I blame you for trashing them.</td>', 'LOL!  Can''t say I blame you for trashing them.', '2007-12-29 05:09:49.000000', NULL, 1),
(4342496, 626155, 30982, '<td valign="top">Not a stupid gift picture, but an adorable picture of an adorable puppy!</td>', 'Not a stupid gift picture, but an adorable picture of an adorable puppy!', '2007-12-29 05:10:44.000000', NULL, 1),
