(4342508, 626187, 30982, '<td valign="top">Money may be an uncreative gift, but rarely is it stupid.  She''s a lovely young lady!  The shot may need a bit of work on white balance - her skin tone is a bit yellow/green, but the monitor I''m using tends to emphasize yellows.</td>', 'Money may be an uncreative gift, but rarely is it stupid.  She''s a lovely young lady!  The shot may need a bit of work on white balance - her skin tone is a bit yellow/green, but the monitor I''m using tends to emphasize yellows.', '2007-12-29 05:16:37.000000', NULL, 1),
(4342509, 626183, 30982, '<td valign="top">That would be foot massager, I think.  If you don''t want it, I''ll gladly take it off your hands.  Or your feet, as the case may be.</td>', 'That would be foot massager, I think.  If you don''t want it, I''ll gladly take it off your hands.  Or your feet, as the case may be.', '2007-12-29 05:17:37.000000', NULL, 1),
(4342511, 625500, 30982, '<td valign="top">Somehow I''m sure you''ll find an interesting use for it...</td>', 'Somehow I''m sure you''ll find an interesting use for it...', '2007-12-29 05:19:51.000000', NULL, 1),
(4342518, 626202, 30982, '<td valign="top">Awwww!  Cute!</td>', 'Awwww!  Cute!', '2007-12-29 05:37:28.000000', NULL, 1),
(4342523, 625635, 30982, '<td valign="top">Nice exposure to keep detail in the black.</td>', 'Nice exposure to keep detail in the black.', '2007-12-29 05:49:11.000000', NULL, 1),
